#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# G019: one fastbox window on the 5600G with several arms (fb_window.sh alternates their order each round), default
# threads, governor performance for its duration. Arms are binaries ~/work/pc/bin/<arm>/monerod, labelled by arm.
# usage: PEER=.. PEER_RPC=.. DD=.. SNAP=.. fbm_pc_window.sh <outdir> <END> <TIMEOUT> <ROUNDS> "<extra args>" <arm>...
# Marker: "FBM_WIN_DONE <rc>" as the last line of <outdir>.fbm.
set -u
K=$HOME/work/fastbox/kit; BIN=$HOME/work/pc/bin
OUT=$1; END=$2; TO=$3; ROUNDS=$4; WX=$5; shift 5; M=$OUT.fbm
args=(); for a in "$@"; do args+=("$a|$BIN/$a/monerod|$WX"); done
G0=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)
echo "$(date -u +%FT%TZ) start $OUT arms=[$*] extra=[$WX] governor $G0; load $(cut -d' ' -f1-3 /proc/loadavg)" > $M
sudo -n cpupower -c all frequency-set -g performance > /dev/null 2>&1 && echo "governor performance" >> $M
bash $K/fb_window.sh "$OUT" "$END" "$TO" "$ROUNDS" "${args[@]}" > $OUT.out 2>&1
rc=$?
sudo -n cpupower -c all frequency-set -g $G0 > /dev/null 2>&1; echo "governor back to $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)" >> $M
echo "$(date -u +%FT%TZ) FBM_WIN_DONE $rc" >> $M
